def solve(grid):
    """
    Transform the input grid according to the discovered rule.

    The input grid contains a central cross (a full row and column) of a unique
    non‑zero colour.  In one of the four quadrants defined by the cross there is
    a pattern of another non‑zero colour.  The output is the grid with the cross
    removed (size reduces by one in each dimension) and the pattern replicated
    in all four quadrants using the cross colour.
    """
    n = len(grid)
    # central index and colour (the cross is always in the centre)
    q = n // 2
    cross_colour = grid[q][q]

    # ------------------------------------------------------------
    # Locate the quadrant that holds the pattern (source quadrant)
    # ------------------------------------------------------------
    source_quad = None
    for i in range(n):
        for j in range(n):
            if i == q or j == q:
                continue
            val = grid[i][j]
            if val != 0 and val != cross_colour:
                if i < q and j < q:
                    source_quad = 'TL'
                elif i < q and j > q:
                    source_quad = 'TR'
                elif i > q and j < q:
                    source_quad = 'BL'
                else:
                    source_quad = 'BR'
                break
        if source_quad:
            break
    if source_quad is None:          # default (should not happen for valid input)
        source_quad = 'TL'

    # ------------------------------------------------------------
    # Extract the pattern mask from the source quadrant
    # ------------------------------------------------------------
    if source_quad == 'TL':
        r0, c0 = 0, 0
        hf, vf = 0, 0
    elif source_quad == 'TR':
        r0, c0 = 0, q + 1
        hf, vf = 1, 0
    elif source_quad == 'BL':
        r0, c0 = q + 1, 0
        hf, vf = 0, 1
    else:  # BR
        r0, c0 = q + 1, q + 1
        hf, vf = 1, 1

    mask = [[0] * q for _ in range(q)]
    for i in range(q):
        for j in range(q):
            val = grid[r0 + i][c0 + j]
            if val != 0 and val != cross_colour:
                mask[i][j] = 1

    # ------------------------------------------------------------
    # Bring the mask to a canonical orientation (TL)
    # ------------------------------------------------------------
    canonical = [[0] * q for _ in range(q)]
    for i in range(q):
        for j in range(q):
            i_src = q - 1 - i if vf else i
            j_src = q - 1 - j if hf else j
            canonical[i][j] = mask[i_src][j_src]

    # ------------------------------------------------------------
    # Build the output grid (size (2q) × (2q))
    # ------------------------------------------------------------
    out_dim = 2 * q
    out = [[0] * out_dim for _ in range(out_dim)]

    # TL – identity
    for i in range(q):
        for j in range(q):
            if canonical[i][j]:
                out[i][j] = cross_colour

    # TR – horizontal flip
    for i in range(q):
        for j in range(q):
            if canonical[i][q - 1 - j]:
                out[i][q + j] = cross_colour

    # BL – vertical flip
    for i in range(q):
        for j in range(q):
            if canonical[q - 1 - i][j]:
                out[q + i][j] = cross_colour

    # BR – both flips
    for i in range(q):
        for j in range(q):
            if canonical[q - 1 - i][q - 1 - j]:
                out[q + i][q + j] = cross_colour

    return out

